+    private static String createDescriptionFileName(String description) {
+        String word = null;
+        Matcher matcher = DESCRIPTION_WORD_PATTERN.matcher(description);
+        while (matcher.find()) {
+            word = matcher.group();
+        }
+        if (word == null) {
+            word = "rule";
+        }
+        String hash = sha256(description);
+        int maximumWordLength = MAX_BUILT_IN_FILE_NAME_LENGTH - hash.length() - 1;
+        if (word.length() > maximumWordLength) {
+            word = word.substring(0, maximumWordLength);
+        }
+        String result = word + "-" + hash;
+        // The hash suffix makes this guard mostly documentary, but keeps the invariant explicit if the implementation changes.
+        return STORED_RULES_FILE_NAME.equals(result) ? "rule-" + hash : result;
+    }
+
+    private static String sha256(String value) {
+        try {
+            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(UTF_8));
+            StringBuilder result = new StringBuilder(digest.length * 2);
+            for (byte item : digest) {
+                result.append(String.format("%02x", item & 0xff));
+            }
+            return result.toString();
+        } catch (NoSuchAlgorithmException e) {
+            throw new IllegalStateException(e);
+        }
+    }
